    if c in ('*', '/'): return 2
    return -1

def main():
    exp = "a+b*(c-d)"
    stack, res = [], []
    for c in exp:
        if c.isalnum(): res.append(c)
        elif c == '(': stack.append(c)
        elif c == ')':
            while stack and stack[-1] != '(': res.append(stack.pop())
            if stack: stack.pop()
        else:
            while stack and prec(c) <= prec(stack[-1]): res.append(stack.pop())
            stack.append(c)
    while stack: res.append(stack.pop())
    print("Postfix: " + "".join(res))

