import threading, time

class Buffer:
    def __init__(self):
        self.cond = threading.Condition()
        self.val = None

    def produce(self, v):
        with self.cond:
            while self.val is not None: self.cond.wait()
            self.val = v
            print(f"Produced: {v}")
            self.cond.notify()

    def consume(self):
        with self.cond:
            while self.val is None: self.cond.wait()
            print(f"Consumed: {self.val}")
            self.val = None
            self.cond.notify()

def main():
    b = Buffer()
    t1 = threading.Thread(target=lambda: [b.produce(i) for i in range(1, 4)])
    t2 = threading.Thread(target=lambda: [b.consume() for _ in range(3)])
    t1.start(); t2.start()
    t1.join(); t2.join()

if __name__ == '__main__':
    main()

