                if (rem[i] > 0) {
                    if (rem[i] > q) { t += q; rem[i] -= q; }
                    else { t += rem[i]; wt[i] = t - burst[i]; rem[i] = 0; done++; }
                }
            }
        }
        System.out.println("Average Waiting Time: " + (wt[0] + wt[1] + wt[2]) / 3.0 + " ms");
    }
}

