public class Main {
    static int minimax(int depth, int nodeIndex, boolean isMax, int[] scores, int h, int alpha, int beta) {
        if (depth == h) return scores[nodeIndex];
        if (isMax) {
            int best = Integer.MIN_VALUE;
            for (int i = 0; i < 2; i++) {
                int val = minimax(depth + 1, nodeIndex * 2 + i, false, scores, h, alpha, beta);
                best = Math.max(best, val); alpha = Math.max(alpha, best);
                if (beta <= alpha) break;
            }
            return best;
        } else {
            int best = Integer.MAX_VALUE;
            for (int i = 0; i < 2; i++) {
                int val = minimax(depth + 1, nodeIndex * 2 + i, true, scores, h, alpha, beta);
                best = Math.min(best, val); beta = Math.min(beta, best);
                if (beta <= alpha) break;
            }
            return best;
        }
